let actx = null;
function audio(){ if(!actx) actx = new (window.AudioContext||window.webkitAudioContext)(); if(actx.state==="suspended") actx.resume(); return actx; }
function env(g, t, a, d, peak){ g.gain.setValueAtTime(0.0001,t); g.gain.linearRampToValueAtTime(peak,t+a); g.gain.exponentialRampToValueAtTime(0.0001,t+a+d); }
function noiseBuf(a, dur){ const n = Math.max(1, Math.floor(a.sampleRate*dur)); const b = a.createBuffer(1,n,a.sampleRate); const d = b.getChannelData(0); for(let i=0;i<n;i++) d[i] = Math.random()*2-1; return b; }
function sfxShoot(p){ const a = audio(); const t = a.currentTime;
  const o = a.createOscillator(); o.type="triangle";
  o.frequency.setValueAtTime(700+300*p, t);
  o.frequency.exponentialRampToValueAtTime(140, t+0.16);
  const g = a.createGain(); env(g,t,0.005,0.18,0.25);
  o.connect(g).connect(a.destination); o.start(t); o.stop(t+0.22);
  const n = a.createBufferSource(); n.buffer = noiseBuf(a,0.12);
  const f = a.createBiquadFilter(); f.type="bandpass"; f.frequency.value=2200; f.Q.value=1;
  const ng = a.createGain(); env(ng,t,0.002,0.1,0.18);
  n.connect(f).connect(ng).connect(a.destination); n.start(t); n.stop(t+0.14);
}
function sfxPop(size){ const a = audio(); const t = a.currentTime;
  const o = a.createOscillator(); o.type="sine";
  const base = 500 + size*140;
  o.frequency.setValueAtTime(base, t);
  o.frequency.exponentialRampToValueAtTime(base*0.4, t+0.09);
  const g = a.createGain(); env(g,t,0.002,0.12,0.4);
  o.connect(g).connect(a.destination); o.start(t); o.stop(t+0.15);
  const n = a.createBufferSource(); n.buffer = noiseBuf(a,0.05);
  const f = a.createBiquadFilter(); f.type="highpass"; f.frequency.value=1800;
  const ng = a.createGain(); env(ng,t,0.001,0.05,0.3);
  n.connect(f).connect(ng).connect(a.destination); n.start(t); n.stop(t+0.06);
}
function sfxMiss(){ const a = audio(); const t = a.currentTime;
  const o = a.createOscillator(); o.type="sine";
  o.frequency.setValueAtTime(220,t); o.frequency.exponentialRampToValueAtTime(90,t+0.15);
  const g = a.createGain(); env(g,t,0.005,0.18,0.15);
  o.connect(g).connect(a.destination); o.start(t); o.stop(t+0.2);
}
